                const before = yield* fs.readFile(target.canonical).pipe(
                  Effect.catchReason("PlatformError", "NotFound", () => Effect.succeed(undefined)),
                )
                yield* permission.assert({
                  action: before === undefined ? "create" : "overwrite",
                  resources: [target.resource],
                  metadata: { path: target.canonical },
                  sessionID: context.sessionID,
                  agent: context.agent,
                  source,
